from collections import deque

# each town and the towns you can reach from it in one step
graph = {"A": ["B", "C"], "B": ["D"], "C": ["D", "E"], "D": ["F"], "E": ["F"], "F": []}
def shortest_path(start, goal):
    queue, came_from = deque([start]), {start: None}
    while queue:
        node = queue.popleft()
        if node == goal:
            path = []
            while node:                  # walk back to the start
                path.append(node)
                node = came_from[node]
            return path[::-1]            # reversed: start first
        for nxt in graph[node]:
            if nxt not in came_from:
                came_from[nxt] = node
                queue.append(nxt)
print(shortest_path("A", "F"))   # ['A', 'B', 'D', 'F']

window = deque(maxlen=3)         # moving average of the last 3 values
for x in [3, 6, 9, 12]:
    window.append(x)
print(list(window), sum(window) / len(window))   # [6, 9, 12] 9.0
d = deque([1, 2, 3, 4]); d.rotate(1)
print(d)                         # deque([4, 1, 2, 3])

from collections import ChainMap, OrderedDict
from collections.abc import Iterable, Mapping, MutableMapping

class CaseInsensitive(MutableMapping):        # keys match whatever their case
    def __init__(self, data=()):
        self._d = {}
        self.update(data)                     # mixin method, supplied for free
    def __getitem__(self, key): return self._d[key.lower()][1]
    def __setitem__(self, key, value): self._d[key.lower()] = (key, value)
    def __delitem__(self, key): del self._d[key.lower()]
    def __iter__(self): return (orig for orig, _ in self._d.values())
    def __len__(self): return len(self._d)

h = CaseInsensitive({"Content-Type": "json"})
print(h["content-type"], "CONTENT-TYPE" in h)   # json True
print(h.get("Accept", "*/*"), list(h))          # */* ['Content-Type']

for obj in [{}, OrderedDict(), ChainMap(), h, [("a", 1)]]:
    print(type(obj).__name__, isinstance(obj, Mapping))   # True except list

class Countdown:
    def __iter__(self): return iter([3, 2, 1])
print(isinstance(Countdown(), Iterable))        # True: judged by its methods

from collections import UserDict

class LowerDict(dict):
    def __setitem__(self, key, value):
        super().__setitem__(key.lower(), value)

class LowerUserDict(UserDict):
    def __setitem__(self, key, value):
        super().__setitem__(key.lower(), value)

a = LowerDict(Name="x")               # creating it skips __setitem__
a.update({"Age": 1})                  # so does update
a["City"] = "Oslo"
print(sorted(a))                      # ['Age', 'Name', 'city']

b = LowerUserDict(Name="x")
b.update({"Age": 1})
b["City"] = "Oslo"
print(sorted(b))                      # ['age', 'city', 'name']

class Fallback(dict):
    def __missing__(self, key):
        return f"<{key}>"
f = Fallback(a=1)
print(f["a"], f["zzz"], f.get("zzz"))  # 1 <zzz> None

import threading
from collections import Counter, deque

def worker(counts, lock, n):
    for _ in range(n):
        with lock:
            counts["hits"] += 1          # compound op: needs the lock

counts, lock = Counter(), threading.Lock()
threads = [threading.Thread(target=worker, args=(counts, lock, 20_000)) for _ in range(4)]
for t in threads: t.start()
for t in threads: t.join()
print(counts["hits"])                    # 80000

def local_count(chunk, results):        # lock-free: count locally, merge later
    results.append(Counter(chunk))
results = deque()                        # deque.append is thread-safe
data = ["x", "y", "x"] * 10_000
chunks = [data[i::4] for i in range(4)]
ts = [threading.Thread(target=local_count, args=(c, results)) for c in chunks]
for t in ts: t.start()
for t in ts: t.join()
print(sum(results, Counter()))           # Counter({'x': 20000, 'y': 10000})
